// Normalise signals into observations WITH COUNTS.
// Deliberately produces no recommendations - that is the 24h loop's job.
// Separating observation from recommendation is what stops the proposal loop
// inventing patterns out of three data points.

const items = $input.all();
const observations = [];

for (const item of items) {
  const payload = item.json || {};
  const signals = Array.isArray(payload.signals) ? payload.signals : [];

  // Group identical or near-identical signals and carry the count through.
  const buckets = {};
  for (const s of signals) {
    const theme = (s.theme || s.text || 'unknown').toLowerCase().trim();
    if (!buckets[theme]) {
      buckets[theme] = { theme, source: s.source || 'unknown', count: 0, examples: [] };
    }
    buckets[theme].count += (s.count || 1);
    if (buckets[theme].examples.length < 3 && s.text) {
      buckets[theme].examples.push(s.text);
    }
  }

  for (const b of Object.values(buckets)) {
    observations.push(b);
  }
}

observations.sort((a, b) => b.count - a.count);

const summary = observations.length
  ? observations.slice(0, 8).map((o) => `- ${o.theme} (${o.source}): ${o.count}`).join('\n')
  : '- no signals in this window';

return [{
  json: {
    collected_at: new Date().toISOString(),
    window_hours: 6,
    observation_count: observations.length,
    observations,
    summary
  }
}];

// Cluster four signal windows into at most three ranked proposals.
// A theme seen fewer than MIN_OCCURRENCES times is discarded, not proposed.
// A proposal without a count is not a proposal, it is a guess.

const MIN_OCCURRENCES = 3;
const MAX_PROPOSALS = 3;

const windows = $input.all().flatMap((i) => {
  const w = i.json.windows || i.json.observations || [];
  return Array.isArray(w) ? w : [];
});

const clustered = {};
for (const o of windows) {
  const theme = (o.theme || 'unknown').toLowerCase().trim();
  if (!clustered[theme]) {
    clustered[theme] = { theme, count: 0, sources: new Set(), examples: [] };
  }
  clustered[theme].count += (o.count || 1);
  if (o.source) clustered[theme].sources.add(o.source);
  for (const ex of (o.examples || [])) {
    if (clustered[theme].examples.length < 3) clustered[theme].examples.push(ex);
  }
}

// Ease is a coarse 1-3 hand-set weight by source type. Frequency does the
// real work; ease only breaks ties between comparable counts.
const EASE = {
  inbox_unfulfilled: 3,
  comments: 3,
  dms: 3,
  web_analytics: 2,
  social_engagement: 2,
  competitor: 1
};

const ranked = Object.values(clustered)
  .filter((c) => c.count >= MIN_OCCURRENCES)
  .map((c) => {
    const sources = Array.from(c.sources);
    const ease = Math.max(...sources.map((s) => EASE[s] || 1));
    return { ...c, sources, ease, score: c.count * ease };
  })
  .sort((a, b) => b.score - a.score)
  .slice(0, MAX_PROPOSALS);

const proposals = ranked.map((r, i) => ({
  rank: i + 1,
  observation: r.theme,
  count: r.count,
  sources: r.sources,
  examples: r.examples,
  proposed_action: 'TO BE DRAFTED by the research agent from this observation',
  owner: 'awaiting human assignment',
  how_we_would_know: 'define a measure before approving',
  requires_approval: true
}));

return [{
  json: {
    generated_at: new Date().toISOString(),
    has_proposals: proposals.length > 0,
    discarded_below_threshold: Object.keys(clustered).length - ranked.length,
    proposal_count: proposals.length,
    proposals
  }
}];
